import { cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();

// Tasks is copied as a standalone static app, so two of the files it loads at runtime are
// generated by this script rather than committed: the vendored Supabase browser bundle and
// env.json. Both are written into the OUTPUT directory, so they do not exist in the source
// tree that `vite dev` serves — which is why Tasks worked in production and died on
// localhost with "Configuration unavailable: Supabase SDK retry failed" after fd6e704
// pointed app.html at the vendored copy. The dev server synthesises the same two files from
// the definitions below (see taskRuntimeDevAssets in vite.config.js), so there is one
// source of truth and dev cannot end up on a different Supabase project than the build.
export const TASK_SUPABASE_SDK_SOURCE = path.join(
    root,
    'node_modules',
    '@supabase',
    'supabase-js',
    'dist',
    'umd',
    'supabase.js',
);

// The vendored task module reads its Supabase connection from env.json. Build it from the
// SAME env vars the host build uses so the two apps can never point at different projects —
// if they do, they hold different login sessions on one origin and the embedded module
// bounces to the host login forever.
// Defaults mirror src/main.js CONFIG; publishable/anon key only, never a secret.
// Trimmed, every one of them. A value pasted into a hosting dashboard picks up a
// trailing newline easily and it is invisible in the UI. It then rides into env.json as
// part of the string: REST survives it, but Realtime puts the key in the WebSocket query
// string where it becomes a literal %0A and the server returns 401. Production shipped
// exactly that until 2026-08-04 -- every request worked and only the socket failed.
export function buildTaskRuntimeEnv() {
    const env = (name, fallback) => String(process.env[name] || fallback).trim();
    const taskRuntimeEnv = {
        supabaseUrl: env('VITE_SUPABASE_URL', 'https://rqundirizvojpzhljtdn.supabase.co'),
        supabaseAnonKey: env('VITE_SUPABASE_ANON_KEY', 'sb_publishable_2WrlRVv2obg2N5g7ifl7Rg_wxGjs29U'),
        sentryDsn: env('VITE_SENTRY_DSN', ''),
        release: env('VERCEL_GIT_COMMIT_SHA', ''),
        turnstileSiteKey: env('VITE_TURNSTILE_SITE_KEY', ''),
    };
    if (/^sb_secret_|service_role/i.test(taskRuntimeEnv.supabaseAnonKey)) {
        throw new Error('Refusing to write a service-role key into taskmanagement/env.json.');
    }
    return taskRuntimeEnv;
}

// Keep in lockstep with LEGACY_ROUTE_SECTIONS in src/main.js. These static stubs
// and the SPA's own legacy normalizer must resolve a given .html path to the same
// section — a host that serves the stub and one that falls through to 404.html
// (the SPA) would otherwise land the same link on two different pages.
const legacyFiles = [
    'admin.html',
    'automations.html',
    'calendar.html',
    'crm.html',
    'dashboards.html',
    'files.html',
    'finance.html',
    'forms.html',
    'jobs.html',
    'knowledge.html',
    'login.html',
    'messages.html',
    'task-management.html',
    'templates.html',
    'tickets.html',
    'underwriter.html',
];

export async function syncSpaAssets(outDirArg = 'dist') {
    const outDir = path.resolve(outDirArg);
    const taskRuntimeSource = path.join(root, 'taskmanagement');
    const taskRuntimeTarget = path.join(outDir, 'taskmanagement');
    const taskSupabaseSource = TASK_SUPABASE_SDK_SOURCE;
    const taskSupabaseTarget = path.join(
        taskRuntimeTarget,
        'vendor',
        'supabase',
        'supabase.js',
    );
    const faviconSource = path.join(root, 'favicon.svg');
    const faviconDarkSource = path.join(root, 'favicon-dark.svg');

    await rm(taskRuntimeTarget, { recursive: true, force: true });
    await cp(taskRuntimeSource, taskRuntimeTarget, { recursive: true });
    // Tasks is copied as a standalone static app, so Vite does not bundle its
    // scripts. Ship Supabase's browser build on our own origin instead of
    // relying on jsDelivr, which the production script-src 'self' policy blocks.
    await mkdir(path.dirname(taskSupabaseTarget), { recursive: true });
    await cp(taskSupabaseSource, taskSupabaseTarget);
    await cp(faviconSource, path.join(outDir, 'favicon.svg'));
    // index.html references both; shipping only one means a 404 for every visitor
    // whose browser prefers a dark colour scheme.
    await cp(faviconDarkSource, path.join(outDir, 'favicon-dark.svg'));

    // Written from the shared builder above, so the dev server and the build cannot drift.
    const taskRuntimeEnv = buildTaskRuntimeEnv();
    await writeFile(
        path.join(taskRuntimeTarget, 'env.json'),
        `${JSON.stringify(taskRuntimeEnv, null, 2)}\n`,
        'utf8',
    );

    // Vite hashes the host assets, but the absorbed Tasks runtime is copied as
    // static files. Give every local script/style a release query so Vercel can
    // cache those large, otherwise-stable files immutably without serving an old
    // file after a deploy. app.html and env.json deliberately remain revalidated.
    const taskRelease = String(
        process.env.VERCEL_GIT_COMMIT_SHA
        || process.env.GITHUB_SHA
        || process.env.GIT_COMMIT_SHA
        || 'local-build',
    ).trim().replace(/[^a-z0-9._-]/gi, '').slice(0, 40) || 'local-build';
    const taskAppPath = path.join(taskRuntimeTarget, 'app.html');
    const taskAppHtml = await readFile(taskAppPath, 'utf8');
    await writeFile(taskAppPath, versionTaskStaticReferences(taskAppHtml, taskRelease), 'utf8');
    await versionTaskCssTree(taskRuntimeTarget, taskRelease);

    const indexHtml = await readFile(path.join(outDir, 'index.html'), 'utf8');
    await writeFile(path.join(outDir, '404.html'), indexHtml);
    await writeFile(path.join(outDir, '.nojekyll'), '');

    await Promise.all(
        legacyFiles.map((file) => writeFile(path.join(outDir, file), legacyRedirect(file, taskRelease), 'utf8'))
    );
}

// Only run the sync when this file IS the process entry point. vite.config.js imports it for
// the dev-server assets above, so an unguarded argv[1] read would also throw whenever a host
// with no script argument loads the config.
if (
    process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
    await syncSpaAssets(process.argv[2] || 'dist');
}

function legacyRedirect(file, release = 'local-build') {
    return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Opening Questbase</title>
    <script src="/legacy-redirect.js?v=${encodeURIComponent(release)}" data-legacy-file="${file}"></script>
  </head>
  <body>
    <p>Opening Questbase...</p>
  </body>
</html>
`;
}

export function versionTaskStaticReferences(html, version) {
    const release = encodeURIComponent(String(version || 'local-build'));
    return String(html || '').replace(
        /(<(?:script|link)\b[^>]*\b(?:src|href)=["'])(?!https?:|\/\/|\/|data:|#)([^"'?#]+)(?:\?[^"']*)?(["'])/gi,
        (_match, prefix, asset, suffix) => `${prefix}${asset}?v=${release}${suffix}`,
    );
}

export function versionTaskCssReferences(css, version) {
    const release = encodeURIComponent(String(version || 'local-build'));
    return String(css || '').replace(
        /(url\(\s*['"]?)(?!https?:|\/\/|\/|data:|#)([^)'"?#]+)(?:\?[^)'" ]*)?(['"]?\s*\))/gi,
        (_match, prefix, asset, suffix) => `${prefix}${asset}?v=${release}${suffix}`,
    );
}

async function versionTaskCssTree(directory, version) {
    const entries = await readdir(directory, { withFileTypes: true });
    await Promise.all(entries.map(async (entry) => {
        const target = path.join(directory, entry.name);
        if (entry.isDirectory()) return versionTaskCssTree(target, version);
        if (!entry.isFile() || !entry.name.toLowerCase().endsWith('.css')) return undefined;
        const css = await readFile(target, 'utf8');
        return writeFile(target, versionTaskCssReferences(css, version), 'utf8');
    }));
}
